export default function AdhesionChart() {
  return (
    <div style={{ background:"#0f0f1a", minHeight:"100vh", color:"#eee",
                  fontFamily:"'Segoe UI',sans-serif", padding:"20px 16px" }}>
      <h2 style={{ textAlign:"center", margin:"0 0 2px", fontSize:18, color:"#7ecfff", letterSpacing:1 }}>
        静止判定データ 比較 — Adhesion係数
      </h2>
      <p style={{ textAlign:"center", margin:"0 0 4px", fontSize:12, color:"#888" }}>
        人工粘性係数 μ = 0.01 固定
      </p>
      <div style={{ textAlign:"center", display:"flex", justifyContent:"center", gap:28, fontSize:13, marginBottom:20 }}>
        <span style={{ color:CA0,  fontWeight:700 }}>━ Ad = 0</span>
        <span style={{ color:CA1,  fontWeight:700 }}>╌ Ad = 1</span>
        <span style={{ color:CA10, fontWeight:700 }}>┄ Ad = 10</span>
      </div>

      <Panel title="① 速度 — RMS速度 & 最大速度" sub="実線 = RMS速度　破線 = 最大速度　単位 (m/s)">
        <ResponsiveContainer width="100%" height={280}>
          <LineChart data={DATA} margin={{top:4,right:24,bottom:14,left:10}}>
            <CartesianGrid {...GRID}/><XAxis {...XAXIS}/>
            <YAxis tick={{fill:"#888",fontSize:10}} label={{value:"速度 (m/s)",angle:-90,position:"insideLeft",fill:"#888",fontSize:11}}/>
            <Tooltip content={<TooltipBox/>}/><ReferenceLine y={0} stroke="#444"/><Legend {...LEG}/>
            <Line type="monotone" dataKey="rms_0"   name="RMS  Ad=0"  stroke={CA0}  strokeWidth={2}   dot={false} isAnimationActive={false} connectNulls={false}/>
            <Line type="monotone" dataKey="vmax_0"  name="Vmax Ad=0"  stroke={CA0}  strokeWidth={1.5} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="6 3"/>
            <Line type="monotone" dataKey="rms_1"   name="RMS  Ad=1"  stroke={CA1}  strokeWidth={2}   dot={false} isAnimationActive={false} connectNulls={false}/>
            <Line type="monotone" dataKey="vmax_1"  name="Vmax Ad=1"  stroke={CA1}  strokeWidth={1.5} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="6 3"/>
            <Line type="monotone" dataKey="rms_10"  name="RMS  Ad=10" stroke={CA10} strokeWidth={2}   dot={false} isAnimationActive={false} connectNulls={false}/>
            <Line type="monotone" dataKey="vmax_10" name="Vmax Ad=10" stroke={CA10} strokeWidth={1.5} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="6 3"/>
          </LineChart>
        </ResponsiveContainer>
      </Panel>

      <Panel title="② 液面高さ & 盛り上がり量" sub="実線 = 壁際液面高さ　破線 = 中心液面高さ　点線 = 盛り上がり量　単位 (mm)">
        <ResponsiveContainer width="100%" height={320}>
          <LineChart data={DATA} margin={{top:4,right:24,bottom:14,left:16}}>
            <CartesianGrid {...GRID}/><XAxis {...XAXIS}/>
            <YAxis tick={{fill:"#888",fontSize:10}} label={{value:"高さ (mm)",angle:-90,position:"insideLeft",fill:"#888",fontSize:11}}/>
            <Tooltip content={<TooltipBox/>}/><ReferenceLine y={0} stroke="#444" strokeDasharray="2 2"/><Legend {...LEG}/>
            <Line type="monotone" dataKey="wall_h_0"    name="壁際 Ad=0"       stroke={CA0}  strokeWidth={2}   dot={false} isAnimationActive={false} connectNulls={false}/>
            <Line type="monotone" dataKey="center_h_0"  name="中心 Ad=0"       stroke={CA0}  strokeWidth={1.5} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="6 3"/>
            <Line type="monotone" dataKey="rise_0"      name="盛り上がり Ad=0"  stroke={CA0}  strokeWidth={1.2} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="2 2"/>
            <Line type="monotone" dataKey="wall_h_1"    name="壁際 Ad=1"       stroke={CA1}  strokeWidth={2}   dot={false} isAnimationActive={false} connectNulls={false}/>
            <Line type="monotone" dataKey="center_h_1"  name="中心 Ad=1"       stroke={CA1}  strokeWidth={1.5} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="6 3"/>
            <Line type="monotone" dataKey="rise_1"      name="盛り上がり Ad=1"  stroke={CA1}  strokeWidth={1.2} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="2 2"/>
            <Line type="monotone" dataKey="wall_h_10"   name="壁際 Ad=10"      stroke={CA10} strokeWidth={2}   dot={false} isAnimationActive={false} connectNulls={false}/>
            <Line type="monotone" dataKey="center_h_10" name="中心 Ad=10"      stroke={CA10} strokeWidth={1.5} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="6 3"/>
            <Line type="monotone" dataKey="rise_10"     name="盛り上がり Ad=10" stroke={CA10} strokeWidth={1.2} dot={false} isAnimationActive={false} connectNulls={false} strokeDasharray="2 2"/>
          </LineChart>
        </ResponsiveContainer>
      </Panel>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(3, 1fr)", gap:12 }}>
        {STATS.map(col => (
          <div key={col.label} style={{ background:"#1a1a2e", border:`1px solid ${col.color}44`, borderRadius:10, padding:"12px 16px" }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:6 }}>
              <span style={{ color:col.color, fontWeight:700, fontSize:14 }}>{col.label}</span>
              <span style={{ color:"#555", fontSize:10, fontFamily:"monospace" }}>{col.config}</span>
            </div>
            <div style={{ color:"#555", fontSize:11, fontFamily:"monospace", marginBottom:8 }}>{col.duration}</div>
            <div style={{ display:"grid", gridTemplateColumns:"130px 1fr 1fr 40px", gap:4, marginBottom:4 }}>
              <div/>
              <div style={{ fontSize:10, color:"#e17055", textAlign:"right" }}>ピーク値</div>
              <div style={{ fontSize:10, color:"#74b9ff", textAlign:"right" }}>最終値</div>
              <div style={{ fontSize:10, color:"#444", textAlign:"right" }}>単位</div>
            </div>
            {col.rows.map(row => (
              <div key={row.label} style={{ display:"grid", gridTemplateColumns:"130px 1fr 1fr 40px", gap:4, marginBottom:3, alignItems:"center" }}>
                <span style={{ fontSize:11, color:"#aaa" }}>{row.label}</span>
                <span style={{ fontSize:12, color:"#e17055", textAlign:"right", fontFamily:"monospace", fontWeight:600 }}>{row.peak}</span>
                <span style={{ fontSize:12, color:"#74b9ff", textAlign:"right", fontFamily:"monospace", fontWeight:600 }}>{row.final}</span>
                <span style={{ fontSize:10, color:"#555", textAlign:"right" }}>{row.unit}</span>
              </div>
            ))}
          </div>
        ))}
      </div>
      <p style={{ textAlign:"center", fontSize:11, color:"#555", marginTop:14 }}>
        ※ 静止判定は frame 120 から開始 ／ 300点リサンプル ／ Ad=0, Ad=10 は frame 479 以降は非表示
      </p>
    </div>
  );
}
